    =&\frac{b^3+a^2b-abc}{2(a^2+b^2)}+\frac{a^4+a^2b^2-a^3c}{2b(a^2+b^2)} 
    =&\frac{b^4+a^2b^2-ab^2c}{2b(a^2+b^2)}+\frac{a^4+a^2b^2-a^3c}{2b(a^2+b^2)} 
    =&\frac{-a^3c-ab^2c+a^4+b^4+2a^2b^2}{2b(a^2+b^2)}.
\end{align*}
